#!/bin/bash
# Copyright (c) 2026 Eclipse ThreadX contributors
# SPDX-License-Identifier: MIT
# Some portions generated by Claude Code (Opus 5).
#
# Run the ZoneX stage-2 probe on the S32Z280-594EVB and capture the evidence:
# the console log and the fault registers.
#
# Usage:  tools/run_zx_probe.sh [<build directory>] [<image name>]
#
# THE CONSOLE IS THE TEST METHOD HERE, NOT A CONVENIENCE.  This captures the
# UART to a FILE before the image runs, and prints the file afterwards.  Two
# LINFlexD bugs found during the Cortex-R52 bring-up were invisible from the
# target and showed up only in a byte diff of a captured log, and the gdb
# report at the end can say what the final state was but never the order the
# events happened in.
#
# NEVER PIPE THIS THROUGH tail OR head.  Redirect to a file and read the file:
# a pipe truncates exactly the part that matters when a run hangs.
#
# Prerequisites this cannot do for you:
#   * the *Windows* CCS listening on 41475, started as "ccs.exe -noportquit".
#     The Linux CCS's pushes to the probe stall after "Sending code ... done".
#   * board wiring for the console: LIN9 -> daughtercard USB-UART, jumper J248
#     at 1-2, micro-USB at J119 on the daughtercard, activity LED J122.
#
# ENVIRONMENT.  Three variables, all REQUIRED, and none of them defaulted --
# because a default would be whichever workstation this script was written on,
# which is wrong for everybody else and tells them where that person's files
# live:
#
#   S32DS_ROOT          the S32 Design Studio installation, the directory
#                       holding S32DS/tools/S32Debugger and S32DS/tools/gdb-arm
#   ZX_PROBE            the debug probe as S32 Design Studio names it, for
#                       example s32dbg:<address of the probe on your network>
#   ZX_GDB_PYTHONHOME   a SOURCE-BUILT Python 3.10 tree.  arm-none-eabi-gdb-py's
#                       embedded interpreter has a minimal builtin set and loads
#                       _struct, _socket and _ctypes as separate .so files, so a
#                       distribution Python will not do.
#
# Optional: UART (default /dev/ttyUSB0) and LOG (default /tmp/zx_probe_uart.log).
set -u

BUILD=${1:-build/s32z280}
IMAGE=${2:-zx_probe.elf}
EVB_BIN="$BUILD/examples/s32z280_evb"
HERE=$(cd "$(dirname "$0")" && pwd)

require() {
    local name=$1 hint=$2
    if [ -z "${!name:-}" ]; then
        echo "ERROR: $name is not set. $hint" >&2
        exit 1
    fi
}

require S32DS_ROOT \
    "Point it at your S32 Design Studio installation -- the directory containing S32DS/tools/S32Debugger."
require ZX_PROBE \
    "Set it to your debug probe as S32 Design Studio names it, for example s32dbg:<probe address>."
require ZX_GDB_PYTHONHOME \
    "Set it to a source-built Python 3.10 tree; gdb-py's embedded interpreter cannot use a distribution one."

GDB=$S32DS_ROOT/S32DS/tools/gdb-arm/arm32-eabi/bin/arm-none-eabi-gdb-py
GTA=$S32DS_ROOT/S32DS/tools/S32Debugger/Debugger/Server/gta

for tool in "$GDB" "$GTA/gta"; do
    if [ ! -x "$tool" ]; then
        echo "ERROR: $tool is not an executable." >&2
        echo "       Is S32DS_ROOT ($S32DS_ROOT) the right installation?" >&2
        exit 1
    fi
done

ELF=$EVB_BIN/$IMAGE
UART=${UART:-/dev/ttyUSB0}
LOG=${LOG:-/tmp/zx_probe_uart.log}

if [ ! -f "$ELF" ]; then
    echo "ERROR: $ELF not found. Build it first:" >&2
    echo "  ./test/s32z280/run.sh build" >&2
    exit 1
fi

# A stray Linux CCS holds 41475 under WSL2 mirrored networking and blocks the
# Windows one.  pkill -x, not -f: it runs as ./ccs, so a -f pattern misses it.
if pgrep -x ccs > /dev/null; then
    echo "ERROR: a Linux CCS is running (pid $(pgrep -x ccs | tr '\n' ' '))." >&2
    echo "       It holds 41475 and blocks the Windows CCS. Kill it: pkill -x ccs" >&2
    exit 1
fi

# /dev/tcp rather than a Python probe, for two reasons: PYTHONHOME below points
# at the source-built 3.10 for gdb-py and would make system python3 fail, and
# ss/netstat inside WSL2 CANNOT SEE a Windows listener at all -- so "nothing is
# listening" from a listing is not evidence.  Test with a connect.
if ! timeout 5 bash -c "exec 3<>/dev/tcp/127.0.0.1/41475" 2>/dev/null; then
    echo "ERROR: nothing listening on 41475." >&2
    echo "       CCS quits when its client disconnects unless started with" >&2
    echo "       -noportquit. Relaunch on Windows as:  ccs.exe -noportquit" >&2
    exit 1
fi

# --- console capture, started BEFORE the image runs -------------------------
if [ -c "$UART" ]; then
    stty -F "$UART" 115200 cs8 -parenb -cstopb -crtscts raw -echo
    : > "$LOG"
    cat "$UART" > "$LOG" &
    CAT_PID=$!
    echo "capturing $UART -> $LOG (pid $CAT_PID)"
else
    CAT_PID=""
    echo "WARNING: $UART is not a character device; running with no console capture." >&2
    echo "         The gdb report at the end still judges the run, but the" >&2
    echo "         ORDER of events will be lost." >&2
fi

cleanup() {
    if [ -n "$CAT_PID" ]; then
        kill "$CAT_PID" 2>/dev/null || true
    fi
}
trap cleanup EXIT

# Computed AFTER every use of the system python3 above: PYTHONHOME pointing at
# the source-built interpreter breaks system tools for the rest of the script,
# which is also why the port check further up uses /dev/tcp rather than Python.
P=$ZX_GDB_PYTHONHOME
export PYTHONHOME=$P
export PYTHONPATH=$P/lib/python3.10:$P/lib/python3.10/lib-dynload:$P/lib/python3.10/site-packages
export ZX_S32Z_ELF=$ELF

# pkill -x, not -f: GTA runs as ./gta, so a -f pattern like 'gta/gta' never
# matches and a stale server silently serves the next attach.
pkill -x gta 2>/dev/null
sleep 2
( cd "$GTA" && nohup ./gta -p 45000 -k > /tmp/gta_zx_probe.log 2>&1 & )
sleep 4
if ! pgrep -x gta > /dev/null; then
    echo "ERROR: GTA failed to start; see /tmp/gta_zx_probe.log" >&2
    exit 1
fi

echo "running $ELF"
timeout -k 20 500 "$GDB" -batch -x "$HERE/run_zx_probe.gdb"
rc=$?

# Let the last of the console output arrive before the capture is torn down.
sleep 2

echo ""
echo "===== console, as captured from $UART ====="
if [ -s "$LOG" ]; then
    cat "$LOG"
else
    echo "(nothing arrived on the console)"
    echo "Check: jumper J248 at 1-2, micro-USB at J119 on the daughtercard, and"
    echo "LED J122 for board-to-host traffic."
fi
echo "===== end of console ====="
echo "=== gdb exit=$rc ==="
exit $rc
